interface Clock {
  now(): Date;
}
class TaskService {
  readonly #titles: { title: string; dueDate: Date }[] = [];
  constructor(private readonly clock: Clock) {}
  add(title: string, daysUntilDue: number): void {
    const dueDate = new Date(this.clock.now().getTime() + daysUntilDue * 86_400_000);
    this.#titles.push({ title, dueDate });
  }
  overdue(): string[] {
    const now = this.clock.now();
    return this.#titles.filter((t) => t.dueDate < now).map((t) => t.title);
  }
}
